import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), q = nextInt();
        long window = nextLong();
        // Pack (time, skill) and (time, query index) into longs so primitive sorts order by time.
        long[] logs = new long[m];
        for (int i = 0; i < m; i++) {
            long skill = nextLong() - 1, time = nextLong();
            logs[i] = (time << 20) | skill;
        }
        Arrays.sort(logs);
        long[] queries = new long[q];
        long[] order = new long[q];
        for (int i = 0; i < q; i++) {
            queries[i] = nextLong();
            order[i] = (queries[i] << 20) | i;
        }
        Arrays.sort(order);
        int mask = (1 << 20) - 1;
        int[] frequency = new int[n], answer = new int[q];
        int active = 0, left = 0, right = 0;
        for (long packed : order) {
            int index = (int) (packed & mask);
            long time = queries[index];
            while (right < m && (logs[right] >> 20) <= time) {
                if (frequency[(int) (logs[right] & mask)]++ == 0) active++;
                right++;
            }
            while (left < right && (logs[left] >> 20) < time - window) {
                if (--frequency[(int) (logs[left] & mask)] == 0) active--;
                left++;
            }
            answer[index] = n - active;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            if (i > 0) out.append(' ');
            out.append(answer[i]);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, q, window := nextInt(), nextInt(), nextInt(), nextInt()
	// Pack (time, skill) and (time, query index) into ints so sorting orders by time.
	const mask = 1<<20 - 1
	logs := make([]int, m)
	for i := range logs {
		skill := nextInt() - 1
		time := nextInt()
		logs[i] = time<<20 | skill
	}
	slices.Sort(logs)
	queries, order := make([]int, q), make([]int, q)
	for i := range queries {
		queries[i] = nextInt()
		order[i] = queries[i]<<20 | i
	}
	slices.Sort(order)
	frequency, answer := make([]int, n), make([]int, q)
	active, left, right := 0, 0, 0
	for _, packed := range order {
		index := packed & mask
		time := queries[index]
		for right < m && logs[right]>>20 <= time {
			skill := logs[right] & mask
			if frequency[skill] == 0 {
				active++
			}
			frequency[skill]++
			right++
		}
		for left < right && logs[left]>>20 < time-window {
			skill := logs[left] & mask
			frequency[skill]--
			if frequency[skill] == 0 {
				active--
			}
			left++
		}
		answer[index] = n - active
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, v := range answer {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(v))
	}
	w.WriteByte('\n')
}
